// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.ocrimport com.roshan.persona.vision.core.ConfidenceTierimport com.roshan.persona.vision.core.ConfidenceTieredResult/** * NOUS — OCR Data Models (Module 6 v4 — Step 6.2). * * Defines all data structures produced by the OCR pipeline: *  - [OcrResult] — full OCR output (text + blocks + extracted fields) *  - [OcrBlock] — one text block with bounding box + confidence *  - [OcrField] — a structured field extracted from raw OCR text *  - [DocumentType] — detected document format (receipt, prescription, ID, etc.) *  - [Prescription] — structured medical prescription *  - [Receipt] — structured receipt *  - [BusinessCard] — structured business card *  - [GovernmentId] — masked PAN/Aadhaar record (privacy-preserved) * * ## Privacy (per strategy v4 §"Privacy & Security") * *  - [OcrResult] and all sub-structures store ONLY text — never raw pixels. *  - [GovernmentId] always stores MASKED numbers (e.g., "XXXX-XXXX-1234") — *    never the full Aadhaar/PAN. The full number is used momentarily for *    structured extraction and then discarded. *  - The 60-second auto-purge for government IDs (v3 §"Privacy") is enforced *    by [PrescriptionScanner] / [GovernmentIdExtractor] callers, not by these *    data classes themselves. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Critical Engineering Fix 4: Dual-Window LCE</a> */// ═══════════════════════════════════════════════════════════════════════════// 1. CORE OCR RESULT// ═══════════════════════════════════════════════════════════════════════════/** * Full output of the OCR pipeline for a single image. * * Contains: *  - [fullText] — concatenated text from all blocks *  - [blocks] — individual text blocks with bounding boxes + confidence *  - [extractedFields] — structured fields (regex-extracted: phones, emails, etc.) *  - [detectedDocumentType] — classification of the document (receipt, prescription, ID, etc.) *  - [structuredDocument] — parsed structured form (prescription/receipt/business card/ID) *  - [enhancementApplied] — true if Image Enhancement Pipeline was used *  - [sourceImageHash] — SHA-256 of the input image (for cache keying; the image itself is NOT stored) *  - [processingTimeMs] — total OCR pipeline duration (preprocessing + ML Kit + field extraction) */data class OcrResult(    val fullText: String,    val blocks: List<OcrBlock>,    val extractedFields: List<OcrField>,    val detectedDocumentType: DocumentType,    val structuredDocument: StructuredDocument?,    val enhancementApplied: Boolean,    val sourceImageHash: String,    val processingTimeMs: Long,    val overallConfidence: Float,) {    /** True if OCR produced any usable text. */    val hasText: Boolean get() = fullText.isNotBlank()    /** True if at least one structured field was extracted. */    val hasFields: Boolean get() = extractedFields.isNotEmpty()    /** Get fields of a specific [OcrFieldType]. */    fun fieldsOfType(type: OcrFieldType): List<OcrField> =        extractedFields.filter { it.type == type }    /** Get the first field of a specific type, or null. */    fun firstFieldOfType(type: OcrFieldType): OcrField? = fieldsOfType(type).firstOrNull()}/** * One text block detected by the OCR engine. * * A "block" is ML Kit's notion of a contiguous text region (paragraph or * visually-grouped text lines). Each block has: *  - [text] — the recognized text *  - [boundingBox] — normalized coordinates (0.0-1.0) of the block in the image *  - [confidence] — ML Kit's recognition confidence (0.0-1.0) *  - [recognizedLanguage] — primary script detected (e.g., "en", "hi", "ta") */data class OcrBlock(    val text: String,    val boundingBox: BoundingBox,    val confidence: Float,    val recognizedLanguage: String?,) {    /** True if this block's confidence meets the HIGH tier (≥ 0.85). */    val isHighConfidence: Boolean        get() = confidence >= 0.85f    /** True if this block's text contains Devanagari characters (Hindi/Marathi/etc.). */    val isDevanagari: Boolean        get() = recognizedLanguage == "hi" || text.any { it.code in 0x0900..0x097F }}/** Normalized bounding box (0.0-1.0 of image dimensions). */data class BoundingBox(    val left: Float,    val top: Float,    val right: Float,    val bottom: Float,) {    init {        require(left in 0f..1f && right in 0f..1f && top in 0f..1f && bottom in 0f..1f) {            "BoundingBox must be normalized (0.0-1.0): left=$left, top=$top, right=$right, bottom=$bottom"        }        require(left < right) { "left must be < right: $left >= $right" }        require(top < bottom) { "top must be < bottom: $top >= $bottom" }    }    val width: Float get() = right - left    val height: Float get() = bottom - top    val area: Float get() = width * height}// ═══════════════════════════════════════════════════════════════════════════// 2. EXTRACTED FIELDS// ═══════════════════════════════════════════════════════════════════════════/** * A structured field extracted from raw OCR text via regex + LLM post-processing. * * Each field has: *  - [type] — what kind of field (phone, email, PAN, Aadhaar, etc.) *  - [value] — the extracted value (normalized) *  - [rawText] — the original text snippet from which it was extracted *  - [confidence] — extraction confidence (0.0-1.0) */data class OcrField(    val type: OcrFieldType,    val value: String,    val rawText: String,    val confidence: Float,) {    /** True if this field's confidence meets the extraction threshold. */    val isReliable: Boolean        get() = confidence >= 0.70f}/** * Types of structured fields extractable from OCR text. * * Includes India-specific formats (PAN, Aadhaar, GSTIN, IFSC, UPI) per v3 §"India-First Design". */enum class OcrFieldType(val displayName: String) {    // ─── Generic ─────────────────────────────────────────────────────────    PHONE_NUMBER("Phone Number"),    EMAIL("Email Address"),    URL("URL"),    DATE("Date"),    TIME("Time"),    MONEY("Money"),    // ─── India-specific ──────────────────────────────────────────────────    INDIAN_PHONE("Indian Phone (+91)"),    INDIAN_PAN("PAN (ABCDE1234F)"),    INDIAN_AADHAAR("Aadhaar (12-digit)"),    INDIAN_GSTIN("GSTIN (15-char)"),    INDIAN_IFSC("IFSC (11-char)"),    INDIAN_UPI_ID("UPI ID (name@bank)"),    INDIAN_CURRENCY("Indian Currency (₹)"),    // ─── Document-specific ───────────────────────────────────────────────    MERCHANT_NAME("Merchant Name"),    RECEIPT_TOTAL("Receipt Total"),    RECEIPT_SUBTOTAL("Receipt Subtotal"),    RECEIPT_TAX("Receipt Tax (GST)"),    RECEIPT_DATE("Receipt Date"),    RECEIPT_ITEMS("Receipt Line Items"),    PERSON_NAME("Person Name"),    ORGANIZATION("Organization"),    ADDRESS("Address"),    JOB_TITLE("Job Title"),    WEBSITE("Website"),    MEDICINE_NAME("Medicine Name"),    MEDICINE_DOSAGE("Medicine Dosage"),    MEDICINE_FREQUENCY("Medicine Frequency"),    DOCTOR_NAME("Doctor Name"),    CLINIC_NAME("Clinic Name"),    PATIENT_NAME("Patient Name"),    DIAGNOSIS("Diagnosis"),    UNKNOWN("Unknown"),}// ═══════════════════════════════════════════════════════════════════════════// 3. DOCUMENT TYPE DETECTION// ═══════════════════════════════════════════════════════════════════════════/** * Type of document detected by [DocumentFormatDetector]. * * Drives which structured extractor runs (Receipt, Prescription, etc.). */enum class DocumentType(val displayName: String) {    /** A retail receipt (Big Bazaar, Reliance, etc.) with items + total. */    RECEIPT("Receipt"),    /** A business card with name, title, company, phone, email. */    BUSINESS_CARD("Business Card"),    /** A medical prescription with medicines + dosages. */    PRESCRIPTION("Medical Prescription"),    /** An invoice/bill with invoice number + line items + GST. */    INVOICE("Invoice"),    /** An Aadhaar card (front or back). Requires explicit opt-in per v3 §"Privacy". */    AADHAAR_CARD("Aadhaar Card"),    /** A PAN card. Requires explicit opt-in per v3 §"Privacy". */    PAN_CARD("PAN Card"),    /** A handwritten note. */    HANDWRITTEN_NOTE("Handwritten Note"),    /** A printed document (book page, contract, etc.). */    PRINTED_DOCUMENT("Printed Document"),    /** A QR code or barcode. */    BARCODE("Barcode"),    /** Unknown — OCR ran but couldn't classify the document. */    UNKNOWN("Unknown"),}// ═══════════════════════════════════════════════════════════════════════════// 4. STRUCTURED DOCUMENTS// ═══════════════════════════════════════════════════════════════════════════/** * Sealed hierarchy of structured documents. * * One of: [Receipt], [BusinessCard], [Prescription], [Invoice], [GovernmentId], [HandwrittenNote]. */sealed interface StructuredDocument {    /** The detected [DocumentType] of this structured doc. */    val documentType: DocumentType    /** A human-readable summary (for TTS readout). */    val summary: String}/** * A retail receipt (Big Bazaar, Amazon delivery, etc.). */data class Receipt(    val merchantName: String?,    val merchantAddress: String?,    val datetime: String?,    val items: List<ReceiptItem>,    val subtotal: Double?,    val tax: Double?,    val total: Double?,    val paymentMethod: String?,    val upiId: String?,) : StructuredDocument {    override val documentType = DocumentType.RECEIPT    override val summary: String = buildString {        merchantName?.let { append("$it. ") }        total?.let { append("Total: ₹$it. ") }        if (items.isNotEmpty()) append("${items.size} items. ")        paymentMethod?.let { append("Paid via $it.") }    }.trim()}/** One line item on a receipt. */data class ReceiptItem(    val name: String,    val quantity: Int,    val price: Double,)/** * A business card. */data class BusinessCard(    val personName: String?,    val jobTitle: String?,    val organization: String?,    val phoneNumbers: List<String>,    val emails: List<String>,    val address: String?,    val website: String?,) : StructuredDocument {    override val documentType = DocumentType.BUSINESS_CARD    override val summary: String = buildString {        personName?.let { append("$it. ") }        jobTitle?.let { append("$it at ") }        organization?.let { append("$it. ") }        if (phoneNumbers.isNotEmpty()) append("Phone: ${phoneNumbers.first()}. ")        if (emails.isNotEmpty()) append("Email: ${emails.first()}.")    }.trim()}/** * A medical prescription. * * Privacy: medications + diagnosis are personal health data. The structured * [Prescription] is stored in encrypted Memory (Module 3) — never synced. */data class Prescription(    val patientName: String?,    val patientAge: String?,    val patientGender: String?,    val doctorName: String?,    val doctorQualification: String?,    val clinicName: String?,    val clinicAddress: String?,    val prescriptionDate: String?,    val medicines: List<PrescriptionMedicine>,    val diagnosis: String?,    val followUpDate: String?,) : StructuredDocument {    override val documentType = DocumentType.PRESCRIPTION    override val summary: String = buildString {        doctorName?.let { append("Dr. $it") }        clinicName?.let { append(", $it") }        append(". ")        patientName?.let { append("Patient: $it. ") }        if (medicines.isNotEmpty()) {            append("${medicines.size} medicines prescribed: ")            append(medicines.take(3).joinToString(", ") { it.name })            if (medicines.size > 3) append(", and ${medicines.size - 3} more")            append(". ")        }        diagnosis?.let { append("Diagnosis: $it. ") }        followUpDate?.let { append("Follow-up: $it.") }    }.trim()}/** One medication entry on a prescription. */data class PrescriptionMedicine(    val name: String,    val dosage: String?,         // "500mg"    val frequency: String?,      // "1 tablet every 6 hours"    val duration: String?,       // "for 5 days"    val instructions: String?,   // "after meals")/** * An invoice (vendor bill). */data class Invoice(    val invoiceNumber: String?,    val vendorName: String?,    val vendorGstin: String?,    val invoiceDate: String?,    val dueDate: String?,    val lineItems: List<ReceiptItem>,    val subtotal: Double?,    val gst: Double?,    val total: Double?,) : StructuredDocument {    override val documentType = DocumentType.INVOICE    override val summary: String = buildString {        vendorName?.let { append("$it. ") }        invoiceNumber?.let { append("Invoice $it. ") }        total?.let { append("Total: ₹$it. ") }        dueDate?.let { append("Due: $it.") }    }.trim()}/** * A government ID record (Aadhaar or PAN). * * ## Privacy (per strategy v3 §"Government ID auto-purge") * *  - The [maskedNumber] ALWAYS contains a masked version (e.g., "XXXX-XXXX-1234"). *  - The full number is NEVER stored here — it's used momentarily for *    structured extraction, then discarded. *  - Raw image is cryptographically shredded (DoD 5220.22-M 3-pass) within *    60 seconds of the scan. *  - This record is stored in encrypted Memory (Module 3) — never synced. */data class GovernmentId(    val idType: GovernmentIdType,    val name: String,    val maskedNumber: String,    val dateOfBirth: String?,    val gender: String?,    val address: String?,    val scanTimestamp: Long,) : StructuredDocument {    override val documentType: DocumentType = when (idType) {        GovernmentIdType.AADHAAR -> DocumentType.AADHAAR_CARD        GovernmentIdType.PAN -> DocumentType.PAN_CARD    }    override val summary: String = buildString {        append("${idType.displayName} for $name. ")        append("Number: $maskedNumber. ")        dateOfBirth?.let { append("DOB: $it. ") }        gender?.let { append("Gender: $it. ") }        append("Scanned on ${java.text.SimpleDateFormat("yyyy-MM-dd HH:mm", java.util.Locale.US).format(java.util.Date(scanTimestamp))}.")    }.trim()}/** Type of government ID. */enum class GovernmentIdType(val displayName: String) {    AADHAAR("Aadhaar Card"),    PAN("PAN Card"),}/** * A handwritten note. */data class HandwrittenNote(    val text: String,    val detectedLanguage: String?,) : StructuredDocument {    override val documentType = DocumentType.HANDWRITTEN_NOTE    override val summary: String = buildString {        append("Handwritten note")        detectedLanguage?.let { append(" in ${languageName(it)}") }        append(": ${text.take(100)}")        if (text.length > 100) append("...")    }.trim()    private fun languageName(code: String): String = when (code) {        "en" -> "English"        "hi" -> "Hindi"        "mr" -> "Marathi"        "ta" -> "Tamil"        "te" -> "Telugu"        "kn" -> "Kannada"        "ml" -> "Malayalam"        "bn" -> "Bengali"        "gu" -> "Gujarati"        "pa" -> "Punjabi"        "or" -> "Odia"        else -> code    }}// ═══════════════════════════════════════════════════════════════════════════// 5. OCR RESULT WRAPPER (tiered)// ═══════════════════════════════════════════════════════════════════════════/** * Tiered OCR result — wraps [OcrResult] with confidence classification. * * Per strategy v4 §"Issue 1: Confidence Thresholds": *  - OCR has no minimum threshold (raw text is always returned). *  - But the [tier] indicates overall recognition quality: *    - HIGH (≥0.85): clean scan, speak full text *    - MEDIUM (0.65-0.85): minor noise, speak text but suggest retake *    - LOW (0.35-0.65): poor scan, don't speak — suggest retake *    - REJECT (<0.35): no usable text — require retake */typealias TieredOcrResult = ConfidenceTieredResult<OcrResult>/** * Build a [TieredOcrResult] from raw OCR data. * * The [overallConfidence] is the average of all block confidences (weighted by block text length). */fun tieredOcrResult(result: OcrResult): TieredOcrResult {    return ConfidenceTieredResult.from(result, result.overallConfidence)}